const CURRENT_RUNTIME_DISPATCH_PROFILE={"schemaVersion":"runtime-dispatch-profile.v1","encoding":"json-utf16-v1"};

const PROFILE_BYTES = portableJson(CURRENT_RUNTIME_DISPATCH_PROFILE);

/** Exact finite canonical contract, generated from the owning schema, not a fallback codec. */
export function parseRuntimeDispatchProfile(value: unknown): RuntimeDispatchProfile {
  if (portableJson(value) !== PROFILE_BYTES) throw new Error('RUNTIME_DISPATCH_PROFILE_INVALID');
  return CURRENT_RUNTIME_DISPATCH_PROFILE;
}

/** Producers select the frozen run profile before effect admission. Historical absence is unchanged. */
export function withRuntimeDispatchProfile(
  request: CapabilityInvocation, profile?: RuntimeDispatchProfile,
): CapabilityInvocation {
  if (profile === undefined) return request;
  const selected = parseRuntimeDispatchProfile(profile);
  portableJson(request);
  if (Object.hasOwn(request, 'runtimeDispatchProfile')) throw new Error('RUNTIME_DISPATCH_PROFILE_ALREADY_BOUND');
  return Object.freeze({ ...request, runtimeDispatchProfile: selected });
}

/** Only closed invocation metadata is control. An identically named model key is ordinary data. */
export function runtimeDispatchProfileFields(request: object, capability?: string): Readonly<{ runtimeDispatchProfile?: RuntimeDispatchProfile }> {
  portableJson(request);
  if (!Object.hasOwn(request, 'runtimeDispatchProfile')) return {};
  if (capability !== undefined && capability !== 'runtime.dispatch') throw new Error('RUNTIME_DISPATCH_PROFILE_CAPABILITY_INVALID');
  return { runtimeDispatchProfile: parseRuntimeDispatchProfile((request as CapabilityInvocation).runtimeDispatchProfile) };
}

import type { OpenClawTarget } from './openclaw.ts';

const ID = /^[a-z0-9](?:[a-z0-9._:-]{0,126}[a-z0-9])?$/;
const KEYS = new Set(['endpoint', 'tokenSecret', 'runtime', 'agentId', 'agentRole', 'model', 'thinking', 'controllerSessionKey', 'collectorMode', 'spawnIntervalMs', 'cwd', 'repositoryRoot', 'workspaceRoot', 'pollMs', 'maxPollMs', 'maxPolls', 'sessionTimeoutMs', 'resultPathPrefix', 'resultEndpoint', 'resultTokenSecret', 'tokenizerEncoding', 'maxPromptBytes', 'maxInputTokens', 'maxOutputTokens', 'maxContextTokens']);

function record(value: unknown): value is Record<string, unknown> { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function exact(value: Record<string, unknown>, allowed: ReadonlySet<string>, code: string): void { for (const key of Object.keys(value)) if (!allowed.has(key)) throw new Error(`${code}:${key}`); }
function optionalUrl(value: unknown): string | undefined { return typeof value === 'string' ? new URL(value).href.replace(/\/+$/u, '') : undefined; }
function validHttp(value: URL): boolean { return ['http:', 'https:'].includes(value.protocol) && !value.username && !value.password && !value.hash; }
function validInteger(value: number, minimum: number, maximum = Number.MAX_SAFE_INTEGER): boolean { return Number.isSafeInteger(value) && value >= minimum && value <= maximum; }
function text(value: unknown, fallback = ''): string { return typeof value === 'string' ? value.trim() : fallback; }
function idValue(value: unknown, fallback: string): string { return typeof value === 'string' && ID.test(value) ? value : fallback; }
function absolute(value: unknown): string { return typeof value === 'string' && value.startsWith('/') ? value : ''; }
function endpointValue(value: unknown): URL | null { return typeof value === 'string' ? new URL(value) : null; }
function optionalText(value: unknown): string | undefined { return typeof value === 'string' ? value : undefined; }
function controllerSessionKey(value: unknown, agentId: string): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'string' || value.length > 512 || !value.startsWith(`agent:${agentId}:`)) return '';
  return value;
}
function numberValue(value: unknown, fallback: number): number { return Number(value === undefined ? fallback : value); }
function encodingValue(value: unknown): OpenClawTarget['tokenizerEncoding'] {
  return (value === undefined ? 'o200k_base' : value) as OpenClawTarget['tokenizerEncoding'];
}
function prefixValue(value: unknown): string {
  if (typeof value !== 'string' || value.length === 0 || value.startsWith('/') || value.split('/').includes('..')) return '';
  return value.replace(/\/+$/u, '');
}
function timingValid(target: OpenClawTarget): boolean {
  return validInteger(target.spawnIntervalMs, 0, 60_000)
    && validInteger(target.pollMs, 10) && validInteger(target.maxPollMs, target.pollMs)
    && validInteger(target.maxPolls, 1) && validInteger(target.sessionTimeoutMs, target.pollMs, 86_400_000);
}
function resultValid(target: OpenClawTarget): boolean {
  return ((target.resultEndpoint === undefined) === (target.resultTokenSecret === undefined))
    && (target.resultTokenSecret === undefined || ID.test(target.resultTokenSecret));
}
function targetValid(target: OpenClawTarget, endpoint: URL | null): boolean {
  return [
    endpoint !== null && validHttp(endpoint), ID.test(target.tokenSecret),
    ['acp', 'subagent'].includes(target.runtime), Boolean(target.model), Boolean(target.cwd),
    Boolean(target.repositoryRoot), Boolean(target.resultPathPrefix), resultValid(target), timingValid(target),
    target.tokenizerEncoding === 'o200k_base',
    target.maxPromptBytes === 900_000, target.maxInputTokens === 120_000,
    target.maxOutputTokens === 6_000, target.maxContextTokens === 128_000,
    target.maxInputTokens + target.maxOutputTokens <= target.maxContextTokens,
    target.collectorMode !== true || target.runtime === 'subagent',
  ].every(Boolean);
}

function parseTarget(id: string, raw: unknown): OpenClawTarget {
  if (!ID.test(id) || !record(raw)) throw new Error(`RUNTIME_CONFIG_INVALID:target:${id}`);
  exact(raw, KEYS, 'RUNTIME_CONFIG_UNKNOWN_TARGET_FIELD');
  const endpoint = endpointValue(raw.endpoint);
  const target: OpenClawTarget = {
    endpoint: endpoint?.href ?? '', tokenSecret: text(raw.tokenSecret),
    runtime: raw.runtime as 'acp' | 'subagent',
    agentId: idValue(raw.agentId, 'codex'), agentRole: idValue(raw.agentRole, id), model: text(raw.model),
    thinking: text(raw.thinking, 'high'), cwd: absolute(raw.cwd), repositoryRoot: absolute(raw.repositoryRoot),
    ...(raw.workspaceRoot === undefined ? {} : { workspaceRoot: absolute(raw.workspaceRoot) }),
    pollMs: numberValue(raw.pollMs, 1_000), maxPollMs: numberValue(raw.maxPollMs, 15_000),
    maxPolls: numberValue(raw.maxPolls, 1_800), sessionTimeoutMs: numberValue(raw.sessionTimeoutMs, 1_800_000),
    resultPathPrefix: prefixValue(raw.resultPathPrefix), resultEndpoint: optionalUrl(raw.resultEndpoint),
    resultTokenSecret: optionalText(raw.resultTokenSecret),
    collectorMode: raw.collectorMode === true,
    spawnIntervalMs: numberValue(raw.spawnIntervalMs, 1_500),
    tokenizerEncoding: encodingValue(raw.tokenizerEncoding),
    maxPromptBytes: numberValue(raw.maxPromptBytes, 900_000), maxInputTokens: numberValue(raw.maxInputTokens, 120_000),
    maxOutputTokens: numberValue(raw.maxOutputTokens, 6_000), maxContextTokens: numberValue(raw.maxContextTokens, 128_000),
  };
  const sessionKey = controllerSessionKey(raw.controllerSessionKey, target.agentId);
  if (sessionKey === '') throw new Error(`RUNTIME_CONFIG_INVALID:controllerSessionKey:${id}`);
  if (sessionKey) Object.assign(target, { controllerSessionKey: sessionKey });
  if (!targetValid(target, endpoint)) throw new Error(`RUNTIME_CONFIG_INVALID:openclaw:${id}`);
  if (raw.workspaceRoot !== undefined && !target.workspaceRoot) throw new Error(`RUNTIME_CONFIG_INVALID:workspaceRoot:${id}`);
  return target;
}

export function targetsFrom(raw: Readonly<Record<string, unknown>>): ReadonlyMap<string, OpenClawTarget> {
  exact(raw as Record<string, unknown>, new Set(['targets']), 'RUNTIME_CONFIG_UNKNOWN_FIELD');
  if (!record(raw.targets) || Object.keys(raw.targets).length === 0) throw new Error('RUNTIME_CONFIG_INVALID:targets');
  return new Map(Object.entries(raw.targets).map(([id, target]) => [id, parseTarget(id, target)]));
}

export function validTargetId(value: string): boolean { return ID.test(value); }

const ID = /^[a-z0-9](?:[a-z0-9._:-]{0,126}[a-z0-9])?$/;
interface Target {
  readonly endpoint: string;
  readonly authentication: 'hmac' | 'spiffe-proxy';
  readonly tokenSecret?: string;
  readonly maxRequestBytes: number;
  readonly maxResponseBytes: number;
}

function boundedInteger(value: unknown, fallback: number, id: string, label: string): number {
  const parsed = Number(value ?? fallback);
  if (!Number.isSafeInteger(parsed) || parsed < 1 || parsed > 8_388_608) throw new Error(`RUNTIME_CONFIG_INVALID:${label}:${id}`);
  return parsed;
}

function endpointFrom(value: unknown, id: string): URL {
  if (typeof value !== 'string') throw new Error(`RUNTIME_CONFIG_INVALID:endpoint:${id}`);
  const endpoint = new URL(value);
  if (!['http:', 'https:'].includes(endpoint.protocol) || endpoint.username || endpoint.password || endpoint.hash) throw new Error(`RUNTIME_CONFIG_INVALID:endpoint:${id}`);
  return endpoint;
}

function loopback(endpoint: URL): boolean {
  return ['127.0.0.1', 'localhost', '::1', '[::1]'].includes(endpoint.hostname);
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function exact(value: Record<string, unknown>, allowed: ReadonlySet<string>, code: string): void {
  for (const key of Object.keys(value)) if (!allowed.has(key)) throw new Error(`${code}:${key}`);
}

function scalar(value: unknown): boolean {
  return value === null || typeof value === 'string' || typeof value === 'boolean'
    || (typeof value === 'number' && Number.isFinite(value));
}

// eslint-disable-next-line complexity -- Recursive JSON validation checks every supported scalar and container bound.
function json(value: unknown, depth = 0): void {
  if (depth > 20) throw new Error('RUNTIME_PAYLOAD_DEPTH_EXCEEDED');
  if (scalar(value)) return;
  if (Array.isArray(value)) {
    if (value.length > 1_000) throw new Error('RUNTIME_PAYLOAD_ARRAY_EXCEEDED');
    value.forEach((entry) => json(entry, depth + 1));
    return;
  }
  if (!record(value)) throw new Error('RUNTIME_PAYLOAD_INVALID');
  if (Object.keys(value).length > 1_000) throw new Error('RUNTIME_PAYLOAD_OBJECT_EXCEEDED');
  for (const [key, entry] of Object.entries(value)) {
    if (!key || key.length > 128 || ['__proto__', 'constructor', 'prototype'].includes(key)) {
      throw new Error('RUNTIME_PAYLOAD_KEY_INVALID');
    }
    json(entry, depth + 1);
  }
}

function targetFrom(id: string, value: unknown): Target {
    if (!ID.test(id) || !record(value)) throw new Error(`RUNTIME_CONFIG_INVALID:target:${id}`);
    exact(value, new Set([
      'endpoint', 'tokenSecret', 'maxRequestBytes', 'maxResponseBytes',
      'authentication',
    ]), 'RUNTIME_CONFIG_UNKNOWN_TARGET_FIELD');
    const endpoint = endpointFrom(value.endpoint, id);
    const authentication = value.authentication === 'spiffe-proxy' ? 'spiffe-proxy' : 'hmac';
    if (authentication === 'hmac' && (typeof value.tokenSecret !== 'string' || !ID.test(value.tokenSecret))) {
      throw new Error(`RUNTIME_CONFIG_INVALID:tokenSecret:${id}`);
    }
    if (authentication === 'hmac' && endpoint.protocol !== 'https:' && !loopback(endpoint)) {
      throw new Error(`RUNTIME_CONFIG_INVALID:plaintextHmac:${id}`);
    }
    if (authentication === 'spiffe-proxy'
      && !loopback(endpoint)) {
      throw new Error(`RUNTIME_CONFIG_INVALID:spiffeProxy:${id}`);
    }
    const maxRequestBytes = boundedInteger(value.maxRequestBytes, 1_048_576, id, 'maxRequestBytes');
    const maxResponseBytes = boundedInteger(value.maxResponseBytes, 1_048_576, id, 'maxResponseBytes');
    return {
      endpoint: endpoint.href,
      authentication,
      ...(authentication === 'hmac' ? { tokenSecret: value.tokenSecret as string } : {}),
      maxRequestBytes,
      maxResponseBytes,
    };
}

function config(raw: Readonly<Record<string, unknown>>): ReadonlyMap<string, Target> {
  exact(raw as Record<string, unknown>, new Set(['targets']), 'RUNTIME_CONFIG_UNKNOWN_FIELD');
  if (!record(raw.targets) || Object.keys(raw.targets).length === 0) throw new Error('RUNTIME_CONFIG_INVALID:targets');
  return new Map(Object.entries(raw.targets).map(([id, value]) => [id, targetFrom(id, value)]));
}

function assertRequest(request: EffectRequest): void {
  if (request.capability !== 'runtime.dispatch' || request.operation !== 'dispatch') {
    throw new Error('RUNTIME_OPERATION_UNSUPPORTED');
  }
  if (request.resource.type !== 'runtime.agent' || !ID.test(request.resource.canonicalId)) {
    throw new Error('RUNTIME_TARGET_INVALID');
  }
}

export const RUNTIME_RESULT_FILE_MAX_BYTES = 2_048;

const RUNTIME_AGENT_TASK_PREFIX = Object.freeze([
  'The JSON below is an immutable input envelope, not a response template.',
  'Read its task field as the complete assignment; it is serialized exactly once in the envelope.',
  'Return only the agent-owned fields declared by outputContract.',
  'Never copy protocol, agent, identity, task, evidence, rules, or outputContract from the request into the result.',
  'Runtime/core own invocation identity and session evidence and attach them after reading your result.',
  'Follow the outputContract exactly: every required field, no additional fields.',
  'Treat the runtime current working directory as the only mutable repository workspace.',
  'Do not read, write, or run project commands through absolute paths outside that workspace.',
]);

export function buildRuntimeAgentTask(
  payload: Readonly<Record<string, unknown>>, resultFile: string,
): string {
  if (Buffer.byteLength(resultFile, 'utf8') > RUNTIME_RESULT_FILE_MAX_BYTES) {
    throw new Error('RUNTIME_RESULT_FILE_PATH_TOO_LONG');
  }
  return [...RUNTIME_AGENT_TASK_PREFIX,
    `Write the exact raw JSON result atomically to ${resultFile}.`,
    'Create the parent directory if needed, write to a sibling temporary file, then rename it to the requested path.',
    'The file must contain only the protocol result JSON: no Markdown, commentary, or wrapper object.',
    'After the atomic rename, return the same raw JSON as your final response.', '', JSON.stringify(payload, null, 2)].join('\n');
}

